import{z as s,x as B,o as e,c as A,q as t,j as r,D as E,d as n,s as l,S as i}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"探索与利用：ε-贪婪与乐观","description":"","frontmatter":{"title":"探索与利用：ε-贪婪与乐观","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/exploration-epsilon.md","filePath":"llm/exploration-epsilon.md","lastUpdated":1791063341000}'),p={name:"llm/exploration-epsilon.md"};function C(m,a,d,h,D,_){const o=B("Mermaid");return e(),A("div",null,[a[2]||(a[2]=t('<h1 id="探索与利用-ε-贪婪与乐观" tabindex="-1">探索与利用：ε-贪婪与乐观 <a class="header-anchor" href="#探索与利用-ε-贪婪与乐观" aria-label="Permalink to &quot;探索与利用：ε-贪婪与乐观&quot;">​</a></h1><div class="epigraph"><p>不吃当前最优的那家馆子，才有机会知道街口新开的那家更好；你学到的价值，只是你自己的动作流过得出的样本。</p><footer>—— 据 Sutton &amp; Barto, Reinforcement Learning: An Introduction, 2018, 第 2 章；Auer, Cesa-Bianchi &amp; Fischer, 2002 整理</footer></div><p><a href="/llm/llm-decision-view">上一课</a>把生成钉成了 MDP：状态是前缀、动作是 token、转移为恒等，维度灾难宣判了表格 DP 的死刑，课程转入无模型——只从策略自己采出的轨迹学习。本课补无模型更早的一个前提：轨迹由策略产生，策略不给的机会价值永远学不到。于是要谈探索-利用权衡，写 ε-贪婪与乐观初始化，再对照 LLM 采样的温度。本单元（MDP 与动态规划）到此收口，它留下的缺口——<strong>无模型时怎么估计价值</strong>——由下一单元开篇的蒙特卡洛策略评估接手。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>评估需要按当前策略采样的轨迹；但若策略只选当前估计的最优动作，次优动作的估值永远停在初值，而当前「最优」可能只是小样本噪声。最小案例是多臂老虎机：动作没有长期后果，每台机器有未知均值。每一步都在花同一份预算：选已知最好的（利用）拿眼前回报，选不确定的（探索）买信息。只利用会被初采样误差锁死，只探索则永远不兑现——这不是工程取舍，是学习问题的内置结构：<strong>信息是动作的副产品</strong>。</p><p><span class="marginnote">「多臂老虎机」就是把探索-利用剥到最简的玩具问题：你面前有几台中奖率未知的老虎机，每拉一次得一次奖励，拉哪台不影响之后的概率。没有状态、没有后续后果，唯一的纠结就是「继续拉现在最赚的那台，还是试试没拉过的」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>ε-贪婪</strong>：以 \\(1-\\varepsilon\\) 概率选当前估值最优的动作，以 \\(\\varepsilon\\) 概率均匀随机探索。表格法的一致性由此买到：每个动作被无穷次访问，大数定律才能把 \\(\\hat Q\\) 拉到真值。代价也明码标价：\\(\\varepsilon\\) 不衰减时，学得再久仍有 \\(\\varepsilon\\) 概率踩次优动作；实战用 \\(\\varepsilon_t\\) 随访问次数或时间衰减，先重探索后重利用。</p><p><span class="marginnote">代个数字感受一下：\\(\\varepsilon=0.1\\) 时每 10 步约有 1 步在随机瞎试，跑 1000 步就约有 100 次「不求眼前回报、只为买信息」的动作。看似浪费，但这些样本正是 \\(\\hat Q\\) 能被拉到真值的原料——没被选中的动作，估值永远停在初值。</span></p><p><strong>乐观初始化</strong>：把 \\(\\hat Q\\) 的初值设得比任何可能回报都高。没被试过的动作显得诱人，被试一次估值猛跌，于是策略系统性地先扫一遍所有动作，再收敛到最优——把「不确定」翻译成「看起来好」，用确定性的初始偏差驱动探索，不需要掷骰子。代价是需要奖励上界的先验，且只天然适配回合初、稀疏交互的场景。更进一步是按不确定度加偏置的置信上界（Auer 等 2002 的 UCB 一族），本课只作锚点，不展开遗憾界分析。</p>',10)),(e(),r(i,null,{default:E(()=>[l(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20OBS%5B%22%E9%9D%A2%E5%AF%B9%E7%8A%B6%E6%80%81%20s%22%5D%20--%3E%20EPS%7B%22%E6%8E%B7%20%CE%B5%20%E7%9A%84%E9%AA%B0%E5%AD%90%22%7D%0A%20%20EPS%20--%3E%7C1%E2%88%92%CE%B5%7C%20GREED%5B%22%E9%80%89%20argmax_a%20Q%CC%82(s%2Ca)%22%5D%0A%20%20EPS%20--%3E%7C%CE%B5%7C%20EXPL%5B%22%E5%9D%87%E5%8C%80%E9%9A%8F%E6%9C%BA%E8%AF%95%E4%B8%80%E4%B8%AA%E5%8A%A8%E4%BD%9C%22%5D%0A%20%20GREED%20--%3E%20R%5B%22%E7%8E%AF%E5%A2%83%E8%BF%94%E5%9B%9E%E5%A5%96%E5%8A%B1%20r%22%5D%0A%20%20EXPL%20--%3E%20R%0A%20%20R%20--%3E%20UPD%5B%22%E6%9B%B4%E6%96%B0%20Q%CC%82%EF%BC%9A%E5%90%91%20r%20%2B%20%E6%8A%98%E6%89%A3%E7%BB%AD%E5%80%BC%E9%9D%A0%E6%8B%A2%22%5D%0A%20%20UPD%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E6%AD%A5%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>与温度的对照要说准。LLM 采样温度把 logits 除以 \\(T\\) 再 softmax，机制与角色见 <a href="/llm/sampling-temperature-topp">温度与 top-p 采样</a>、训练期用法见 <a href="/llm/rl-sampling-temperature">RL 采样温度</a>。它像探索，但有三个差距：其一，温度是逐步独立的扰动，不随经验收敛——ε-贪婪的探索随 \\(\\hat Q\\) 变准而自然失去意义，温度则永远同样地摇，退火要另加调度；其二，它不保证覆盖：温度升高后概率质量仍在头部打转，长尾 token 几乎不被采到，「试过」这件事没有保证，而 ε-贪婪与乐观法的关键产物恰恰是每个动作的无穷访问；其三，服务对象不同：推理期温度管输出多样性，训练期探索要服务价值估计的一致性，预算与判据不能共用。所以温度不是探索的完整答案，rollout 的覆盖还是要按「每个状态-动作被访问多少次」来盯。</p><p><span class="marginnote">ε-贪婪的渐近代价可以写成份额：\\(\\varepsilon=0.1\\) 不衰减时，无论学多久都有约一成动作花在均匀瞎试上，遗憾随交互次数线性增长；衰减调度的意义正是把这份预算从「永久保险」改成「前期投入」。</span></p><p><span class="marginnote">初学者容易把「调高温度」当成探索。实际上温度只是把整张概率分布抹平一点：头部 token 概率仍占大头，长尾 token 几乎永远轮不到被采到——这与 ε-贪婪「保证每个动作都被访问到」是两码事。</span></p><p>乐观初始化为什么不用掷骰子也能扫遍所有动作，把它的循环画出来一目了然：</p>',5)),(e(),r(i,null,{default:E(()=>[l(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20LR%0A%20%20INIT%5B%22%E6%89%80%E6%9C%89%E5%8A%A8%E4%BD%9C%20Q%CC%82%20%E5%88%9D%E5%80%BC%E8%AE%BE%E5%BE%97%E5%BE%88%E9%AB%98%22%5D%20--%3E%20TRY%5B%22%E8%B4%AA%E5%BF%83%E9%80%89%E5%BD%93%E5%89%8D%E4%BC%B0%E5%80%BC%E6%9C%80%E9%AB%98%E7%9A%84%E5%8A%A8%E4%BD%9C%22%5D%0A%20%20TRY%20--%3E%20OBS%5B%22%E8%A7%82%E5%AF%9F%E5%88%B0%E7%9C%9F%E5%AE%9E%E5%A5%96%E5%8A%B1%EF%BC%8C%E4%BD%8E%E4%BA%8E%E5%88%9D%E5%80%BC%22%5D%0A%20%20OBS%20--%3E%20FALL%5B%22%E8%AF%A5%E5%8A%A8%E4%BD%9C%E4%BC%B0%E5%80%BC%E5%A4%A7%E8%B7%8C%22%5D%0A%20%20FALL%20--%3E%20Q%7B%22%E8%BF%98%E6%9C%89%E6%B2%A1%E8%AF%95%E8%BF%87%E7%9A%84%E9%AB%98%E5%88%9D%E5%80%BC%E5%8A%A8%E4%BD%9C%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%E6%98%AF%7C%20TRY%0A%20%20Q%20--%3E%7C%E5%90%A6%7C%20CONV%5B%22%E5%85%A8%E9%83%A8%E6%89%AB%E8%BF%87%EF%BC%8C%E6%94%B6%E6%95%9B%E5%88%B0%E7%9C%9F%E6%9C%80%E4%BC%98%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课的探索都是动作级的（试不同 token），不含定向探索（按计数或好奇心去没去过的状态），也不含 prompt 层面的任务多样性——那是数据配比的问题。乐观法在随机奖励、非平稳环境下会失效或需改造；UCB 与 Thompson 采样的遗憾界不在本课。还有一个本课刻意留下的缺口：ε-贪婪与乐观都假设<strong>已经有了</strong> \\(\\hat Q\\) 可以贪心、可以初始化——无模型时 \\(\\hat Q\\) 从哪来、采样轨迹怎么折算成估值，上一课维度灾难之后悬着的这个问题，下一单元从蒙特卡洛策略评估讲起。</p><p>后课默认：探索保证的是访问次数，估计由后面的方法负责；两笔账分开算。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>探索-利用权衡的根源：信息是动作的副产品，覆盖不到就学不到。</li><li>ε-贪婪买访问次数：一致性有保证，代价是 \\(\\varepsilon\\) 份额的次优动作，用衰减调度消化。</li><li>乐观初始化把不确定翻译成有吸引力：确定性探索，需要奖励上界先验。</li><li>温度不是探索的完整答案：不随经验收敛、不保证覆盖、服务多样性而非估计。</li><li>本单元收口：五元组、回报、贝尔曼、DP、生成视角、探索备齐；无模型估计留待蒙特卡洛。</li><li>出处：Sutton &amp; Barto 2018 第 2 章；Auer, Cesa-Bianchi &amp; Fischer, <em>Machine Learning</em>, 2002。</li></ul>',5))])}const T=s(p,[["render",C]]);export{u as __pageData,T as default};
